CREATE TABLE `role_capabilities` (`role_code` VARCHAR(64) CHARACTER SET ascii NOT NULL,`capability_code` VARCHAR(80) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`role_code`,`capability_code`),KEY `idx_role_capability_capability`(`capability_code`,`role_code`),CONSTRAINT `fk_role_capabilities_role` FOREIGN KEY(`role_code`) REFERENCES `roles`(`code`) ON DELETE RESTRICT,CONSTRAINT `fk_role_capabilities_capability` FOREIGN KEY(`capability_code`) REFERENCES `capabilities`(`code`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
